#include <algorithm>
#include <vector>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
   int highestDegree = 0;

   // Use a threshold for small inputs
   const size_t threshold = 100;

   if (N < threshold) {
      // Compute degree for each row in a serial loop
      for (int i = 0; i < N; i += 1) {
         int degree = 0;
         for (int j = 0; j < N; j += 1) {
             degree += A[i * N + j];
         }
         highestDegree = std::max(highestDegree, degree);
      }
   } else {
      // Use OpenMP for larger inputs
      #pragma omp parallel
      {
         int localMaxDegree = 0;
         #pragma omp for
         for (int i = 0; i < N; i += 1) {
            int degree = 0;
            for (int j = 0; j < N; j += 1) {
                degree += A[i * N + j];
            }
            localMaxDegree = std::max(localMaxDegree, degree);
         }
         // Combine the local max degrees in a critical section to avoid race conditions
         #pragma omp critical
         {
            highestDegree = std::max(highestDegree, localMaxDegree);
         }
      }
   }
   return highestDegree;
}

