int maxDegreeSIMD(std::vector<int> const& A, size_t N) {
    int highestDegree = 0;
    const int* data = A.data();
    for (int i = 0; i < N; i += 1) {
        int degree = 0;
        int j = 0;
        for (; j + 4 < N; j += 4) {
            __m128i a = _mm_loadu_si128((__m128i*)&data[i * N + j]);
            degree += _mm_popcnt_u32(_mm_movemask_epi8(a));
        }
        for (; j < N; j += 1) {
            degree += data[i * N + j];
        }
        highestDegree = std::max(highestDegree, degree);
    }
    return highestDegree;
}

