int maxDegree(std::vector<int> const& A, size_t N) {
   int highestDegree = 0;
   for (int i = 0; i < N; i += 1) {
      int degree = 0;
      // Process 4 elements at a time using SIMD instructions
      int j;
      for (j = 0; j <= N - 4; j += 4) {
         __m128i a = _mm_loadu_si128((__m128i*)&A[i * N + j]);
         degree += _mm_popcnt_u32(_mm_movemask_epi8(a));
      }
      // Handle remaining elements
      for (; j < N; j++) {
         degree += A[i * N + j];
      }
      highestDegree = std::max(highestDegree, degree);
   }
   return highestDegree;
}

