#pragma once
#include <array>
#include <vector>

/* Vector x contains values between 0 and 100, inclusive. Count the number of
   values in [0,10), [10, 20), [20, 30), ... and store the counts in `bins`.
   Example:

   input: [7, 32, 95, 12, 39, 32, 11, 71, 70, 66]
   output: [1, 2, 0, 3, 0, 0, 1, 2, 0, 1]
*/
void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
   for (size_t i = 0; i < x.size(); i += 1) {
      const size_t bin = x[i] / 10;
      bins[bin] += 1;
   }
}

outputs:
#include <array>
#include <vector>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize bins to 0
    #pragma omp parallel for
    for (size_t i = 0; i < 10; i++) {
        bins[i] = 0;
    }

    // Use OpenMP for parallelizing the counting process
    #pragma omp parallel
    {
        // Local bins for each thread
        std::array<size_t, 10> local_bins = {0};

        // Each thread processes a chunk of the input vector
        #pragma omp for
        for (size_t i = 0; i < x.size(); i++) {
            const size_t bin = x[i] / 10;
            local_bins[bin]++;
        }

        // Combine local bins to global bins
        #pragma omp critical
        {
            for (size_t j = 0; j < 10; j++) {
                bins[j] += local_bins[j];
            }
        }
    }
}

