#pragma once
#include <vector>
#include <array>
#include <immintrin.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    const size_t size = image.size();
    const size_t step = 16;

    // Process data in chunks using SIMD instructions
    for (size_t i = 0; i < size; i += step) {
        __m128i counts = _mm_setzero_si128();
        for (size_t j = 0; j < step && (i + j) < size; ++j) {
            counts = _mm_add_epi32(counts, _mm_set1_epi32(1));
        }
        // Horizontal addition of the 16 32-bit integers
        int binIndices[16];
        _mm_store_si128((__m128i*)binIndices, counts);
        for (int k = 0; k < 16; ++k) {
            if ((i + k) < size) {
                bins[image[i + k]] += binIndices[k];
            }
        }
    }

    // Process remaining elements
    for (size_t i = size - (size % step); i < size; ++i) {
        bins[image[i]] += 1;
    }
}

