void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    // Reset the bins to 0
    for (size_t i = 0; i < 4; ++i) {
        bins[i] = 0;
    }

    // Use local variables for better performance
    size_t zeroBin = 0;
    size_t oneBin = 0;
    size_t twoBin = 0;
    size_t threeBin = 0;

    for (auto const& point : points) {
        if (point.x >= 0 && point.y >= 0) {
            zeroBin++;
        } else if (point.x < 0 && point.y >= 0) {
            oneBin++;
        } else if (point.x < 0 && point.y < 0) {
            twoBin++;
        } else if (point.x >= 0 && point.y < 0) {
            threeBin++;
        }
    }

    // Store the results in the bins array
    bins[0] = zeroBin;
    bins[1] = oneBin;
    bins[2] = twoBin;
    bins[3] = threeBin;
}

