double sumOfPrefixSum(std::vector<double> const& x) {
    if (x.empty()) return 0.0;
    if (x.size() < 16) {
        // For small sizes, use sequential computation for speed.
        double sum = 0.0;
        for (double num : x) {
            sum += num;
        }
        return sum;
    }

    // For larger sizes, use parallel computation with reduction for better performance.
    double totalSum = 0.0;
    #pragma omp parallel
    {
        double localSum = 0.0;
        #pragma omp for nowait
        for (size_t i = 0; i < x.size(); ++i) {
            localSum += x[i];
        }
        // Combine the results from each thread into totalSum using atomic operations for thread safety.
        #pragma omp critical
        totalSum += localSum;
    }
    return totalSum;
}

