        // Determine the maximum thread count
        int max_threads = omp_get_max_threads();
        int chunk_size = (n + max_threads - 1) / max_threads;

        #pragma omp for
        for (size_t i = 0; i < n; i += chunk_size) {
            float local_min = x[i];
            for (size_t j = i + 1; j < std::min(i + chunk_size, n); ++j) {
                local_min = std::min(local_min, x[j]);
            }
            // Reduce the local minimum to the correct position
            #pragma omp critical
            x[i] = std::min(x[i], local_min);
        }
    }

    // Final pass to propagate the minimums to the right
    for (size_t i = 1; i < n; ++i) {
        x[i] = std::min(x[i], x[i - 1]);
    }
}

