#include <immintrin.h>

void relu(std::vector<double> &x) {
    const __m256d zero = _mm256_setzero_pd();
    const __m256d threshold = _mm256_set1_pd(0.0);

    size_t i = 0;
    for (; i + 8 <= x.size(); i += 8) {
        __m256d values = _mm256_loadu_pd(&x[i]);
        __m256d cmp = _mm256_cmp_pd(values, threshold, _CMP_LT_OQ);
        values = _mm256_and_pd(values, cmp);
        _mm256_storeu_pd(&x[i], values);
    }

    for (; i < x.size(); ++i) {
        x[i] = std::max(0.0, x[i]);
    }
}

