void relu(std::vector<double> &x) {
    const __m256d zero = _mm256_setzero_pd();
    const int n = x.size();
    int i = 0;

    // Process 4 elements at a time using SIMD instructions
    for (; i + 4 <= n; i += 4) {
        __m256d values = _mm256_loadu_pd(&x[i]);
        values = _mm256_max_pd(zero, values);
        _mm256_storeu_pd(&x[i], values);
    }

    // Handle remaining elements
    for (; i < n; ++i) {
        x[i] = std::max(0.0, x[i]);
    }
}

