void negateOddsAndHalveEvens(std::vector<int> &x) {
    const size_t size = x.size();
    const size_t halfSize = size / 2;
    const size_t remainder = size % 2;

    // Use loop unrolling for performance
    size_t i = 0;
    for (; i < halfSize; i += 2) {
        x[i] /= 2;
        x[i + 1] /= 2;
    }

    // Handle remaining elements
    for (; i < size; ++i) {
        x[i] /= 2;
    }

    // Use SIMD instructions for even elements
    for (i = 0; i < halfSize; i += 4) {
        __m256i values = _mm256_loadu_si256((__m256i*)&x[i]);
        values = _mm256_srai_epi32(values, 1); // Divide by 2
        _mm256_storeu_si256((__m256i*)&x[i], values);
    }

    // Handle remaining elements
    for (; i < halfSize; ++i) {
        x[i] /= 2;
    }

    // Negate odd elements
    for (i = 0; i < size; i += 2) {
        x[i] = -x[i];
        if (i + 1 < size) {
            x[i + 1] = -x[i + 1];
        }
    }
