   }

   // LU factorization algorithm with loop unrolling and parallelization
   #pragma omp parallel for
   for (size_t i = 0; i < N; ++i) {
      for (size_t j = 0; j < N; j += 4) {
         if (j < i) {
            U[i * N + j] = fullA[i][j];
            if (j > 0) U[i * N + j] -= L[i * N + j - 1] * U[(j - 1) * N + j];
            if (j > 1) U[i * N + j] -= L[i * N + j - 2] * U[(j - 2) * N + j];
            if (j > 2) U[i * N + j] -= L[i * N + j - 3] * U[(j - 3) * N + j];
         } else {
            if (j < i) {
               L[i * N + j] = fullA[i][j] / U[j * N + j];
            } else {
               L[i * N + j] = 1;
            }
            if (j + 1 < N) {
               U[i * N + j + 1] = fullA[i][j + 1];
               U[i * N + j + 1] -= L[i * N + j] * U[j * N + j + 1];
            }
            if (j + 2 < N) {
               U[i * N + j + 2] = fullA[i][j + 2];
               U[i * N + j + 2] -= L[i * N + j] * U[j * N + j + 2];
            }
            if (j + 3 < N) {
               U[i * N + j + 3] = fullA[i][j + 3];
