#include <vector>
#include <omp.h>

void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
   // Initialize fullA to zero
   std::vector<std::vector<double>> fullA(N, std::vector<double>(N, 0));

   // Fill fullA in a single loop
   for (const auto& element : A) {
      fullA[element.row][element.column] = element.value;
   }

   // LU factorization algorithm with loop unrolling and cache optimization
   #pragma omp parallel for
   for (size_t i = 0; i < N; ++i) {
      for (size_t j = 0; j < N; j += 4) {
         double sumU = 0.0;
         double sumL = 0.0;
         double u1 = 0.0, u2 = 0.0, u3 = 0.0, u4 = 0.0;

         // Compute U[i][j] for j < i
         for (size_t k = 0; k < i; ++k) {
            sumU += L[i * N + k] * U[k * N + j];
         }

         // Compute U[i][j] for j < i
         if (j < i) {
            U[i * N + j] = fullA[i][j] - sumU;
         } else {
            u1 = fullA[i][j]; u2 = fullA[i][j+1]; u3 = fullA[i][j+2]; u4 = fullA[i][j+3];
            U[i * N + j]   = u1 - sumU;
            U[i * N + j+1] = u2 - sumU;
            U[i * N + j+2] = u3 - sumU;
            U[i * N + j+3] = u4 - sumU;
         }

         // Compute L[i][j] for j < i
         if (j < i) {
            L[i * N + j] = fullA[i][j] / U[j * N + j] - sumL;
         } else {
            L[i * N + j]   = (fullA[i][j]   / U[j * N + j]) - sumL;
            L[i * N + j+1] = (fullA[i][j+1] / U[(j+1) * N + j+1]) - sumL;
            L[i * N + j+2] = (fullA[i][j+2] / U[(j+2) * N + j+2]) - sumL;
            L[i * N + j+3] = (fullA[i][j+3] / U[(j+3) * N + j+3]) - sumL;
         }
      }
      // Set L[i][i] = 1
      L[i * N + i] = 1.0;
   }
}

