    unsigned int N = output.size();
    if (N == 0) return;

    // Bit reversal
    unsigned int m = (unsigned int)std::log2(N);
    #pragma omp parallel for
    for (unsigned int a = 0; a < N; a++) {
        unsigned int b = a;
        // Reverse bits
        b = (((b & 0xaaaaaaaa) >> 1) | ((b & 0x55555555) << 1));
        b = (((b & 0xcccccccc) >> 2) | ((b & 0x33333333) << 2));
        b = (((b & 0xf0f0f0f0) >> 4) | ((b & 0x0f0f0f0f) << 4));
        b = (((b & 0xff00ff00) >> 8) | ((b & 0x00ff00ff) << 8));
        b = ((b >> 16) | (b << 16)) >> (32 - m);
        if (b > a) {
            std::complex<double> t = output[a];
            output[a] = output[b];
            output[b] = t;
        }
    }

    // Cooley-Tukey FFT
    double thetaT = 2.0 * M_PI / N;
    std::complex<double> phiT(std::cos(thetaT), std::sin(thetaT));
    unsigned int n, k = N / 2;
    while (k > 0) {
        n = k;
        k /= 2;
        phiT = phiT * phiT;
        #pragma omp parallel for
        for (unsigned int l = 0; l < k; l++) {
            std::complex<double> omega(1.0, 0.0);
            for (unsigned int a = l; a < N; a += n) {
                unsigned int b = a + k;
                std::complex<double> t = output[a] - output[b];
                output[a] += output[b];
                output[b] = t * omega;
                omega *= phiT;
            }
        }
    }
