#endif

void fft(std::vector<std::complex<double>> const& x, std::vector<std::complex<double>> &output) {
    unsigned int N = x.size();
    if (N <= 1) return;

    output.resize(N);
    #pragma omp parallel
    {
        unsigned int thread_count = omp_get_num_threads();
        unsigned int thread_id = omp_get_thread_num();
        unsigned int chunk_size = (N + thread_count - 1) / thread_count;
        unsigned int start = thread_id * chunk_size;
        unsigned int end = std::min(start + chunk_size, N);

        // Local computation using Danielson-Lanczos lemma
        for (unsigned int m = 1; m < N; m *= 2) {
            double theta = -2 * M_PI / (2 * m);
            std::complex<double> wm = std::complex<double>(std::cos(theta), std::sin(theta));
            #pragma omp for
            for (unsigned int k = start; k < end; k += m) {
                std::complex<double> w = std::complex<double>(1.0, 0.0);
                for (unsigned int j = 0; j < m / 2; ++j) {
                    unsigned int evenIndex = k + j;
                    unsigned int oddIndex = k + j + m / 2;
                    std::complex<double> temp = w * x[oddIndex];
                    output[evenIndex] += temp;
                    output[oddIndex] = x[evenIndex] - temp;
                    w *= wm;
                }
            }
        }
    }

    // Combine results from each thread
    #pragma omp single
    {
        for (unsigned int i = 1; i < N; i *= 2) {
            for (unsigned int j = 0; j < N; j += 2 * i) {
                for (unsigned int k = 0; k < i; ++k) {
                    unsigned int evenIndex = j + k;
                    unsigned int oddIndex = j + k + i;
                    std::complex<double> temp = output[oddIndex] * std::complex<double>(std::cos(M_PI * k / i), -std::sin(M_PI * k / i));
                    output[evenIndex] += temp;
                    output[oddIndex] = output[evenIndex] - temp;
                }
            }
        }
    }
}

