void fft_impl(std::vector<std::complex<double>> &x, bool inverse) {
    const size_t n = x.size();
    if (n == 0) return;

    // Bit reversal permutation
    size_t j = 0;
    for (size_t i = 0; i < n - 1; ++i) {
        if (i < j) std::swap(x[i], x[j]);

        size_t m = n >> 1;
        while (j >= m) {
            j -= m;
            m >>= 1;
        }
        j += m;
    }

    // Cooley-Tukey FFT
    #pragma omp parallel for
    for (size_t len = 2; len <= n; len <<= 1) {
        const double angle_increment = (inverse? -1.0 : 1.0) * 2.0 * M_PI / static_cast<double>(len);
        std::complex<double> wlen(cos(angle_increment), sin(angle_increment));
        for (size_t i = 0; i < n; i += len) {
            std::complex<double> w(1.0, 0.0);
            for (size_t j = 0; j < len / 2; ++j) {
                std::complex<double> temp = w * x[i + j + len / 2];
                std::complex<double> t = x[i + j];
                x[i + j] = t + temp;
                x[i + j + len / 2] = t - temp;
                w *= wlen;
            }
        }
    }

    // Scaling for inverse FFT
    if (inverse) {
        for (size_t i = 0; i < n; ++i) {
            x[i] /= static_cast<double>(n);
        }
    }
}

