void fft_impl(std::vector<std::complex<double>> &x, bool inverse) {
    const size_t n = x.size();
    if (n == 0) return;

    // Rearrange the elements to improve cache performance
    #pragma omp parallel
    {
        #pragma omp for
        for (size_t i = 0; i < n; ++i) {
            size_t reversed = 0;
            size_t temp = i;
            for (size_t j = 0; j < sizeof(size_t) * 8; ++j) {
                reversed <<= 1;
                reversed |= temp & 1;
                temp >>= 1;
            }
            if (i < reversed) {
                std::swap(x[i], x[reversed]);
            }
        }
    }

    // Compute the FFT
    size_t levels = 0;
    size_t size = n;
    while (size > 1) {
        size >>= 1;
        ++levels;
    }

    for (size_t step = 0; step < levels; ++step) {
        size_t stride = 1 << step;
        size_t group_count = 1 << (levels - step - 1);

        #pragma omp parallel for
        for (size_t group = 0; group < group_count; ++group) {
            size_t group_start = group * stride * 2;
            for (size_t i = group_start; i < group_start + stride; ++i) {
                std::complex<double> temp = x[i + stride];
                std::complex<double> w = std::polar(1.0, (inverse? -1.0 : 1.0) * 2.0 * M_PI * static_cast<double>(i - group_start) / static_cast<double>(stride));
                x[i + stride] = x[i] - temp * w;
                x[i] += temp * w;
            }
        }
    }

    if (inverse) {
        // Scale the results to get the inverse FFT
        for (size_t i = 0; i < n; ++i) {
            x[i] /= static_cast<double>(n);
        }
    }
}

