    const size_t n = x.size();
    if (n == 0) return;

    // Bit reversal permutation
    size_t j = 0;
    for (size_t i = 0; i < n - 1; ++i) {
        if (i < j) std::swap(x[i], x[j]);

        size_t m = n >> 1;
        while (j >= m) {
            j -= m;
            m >>= 1;
        }
        j += m;
    }

    // Cooley-Tukey decimation in time radix-2 FFT
    for (size_t s = 1; s < n; s *= 2) {
        const double theta = (inverse? -2.0 : 2.0) * M_PI / (2.0 * s);
        const std::complex<double> ws(cos(theta), sin(theta));

        #pragma omp parallel for
        for (size_t k = 0; k < n; k += s * 2) {
            std::complex<double> w(1.0, 0.0);
            for (size_t j = 0; j < s; ++j) {
                const std::complex<double> t = w * x[k + j + s];
                const std::complex<double> u = x[k + j];
                x[k + j] = u + t;
                x[k + j + s] = u - t;
                w *= ws;
            }
        }
    }

    // Scaling for inverse FFT
    if (inverse) {
        #pragma omp parallel for
        for (size_t i = 0; i < n; ++i) {
            x[i] /= static_cast<double>(n);
        }
    }
}

