    for (size_t i = 0; i < points.size(); ++i) {
        if (i == std::distance(points.begin(), leftmost)) continue;
        while (upperHull.size() > 1 && cross(upperHull[upperHull.size() - 2], upperHull.back(), points[i]) <= 0) {
            upperHull.pop_back();
        }
        upperHull.push_back(points[i]);
    }

    // Build lower hull
    for (size_t i = points.size() - 1; i < points.size(); --i) {
