        if (crossProduct == 0) {
            // Use distance as a tiebreaker if the points are collinear
            double distA = (a.x - leftmost->x) * (a.x - leftmost->x) + (a.y - leftmost->y) * (a.y - leftmost->y);
            double distB = (b.x - leftmost->x) * (b.x - leftmost->x) + (b.y - leftmost->y) * (b.y - leftmost->y);
            return distA < distB;
        }
        return crossProduct > 0;
    });

    // Build the convex hull
    hull.reserve(points.size());
    hull.push_back(*leftmost);
    for (size_t i = 0; i < sortedPoints.size(); ++i) {
