void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Find the lowest point
    auto it = std::min_element(points.begin(), points.end(), [](Point const& a, Point const& b) {
        return a.y < b.y || (a.y == b.y && a.x < b.x);
    });
    Point lowest = *it;

    // Sort the points by polar angle with the lowest point
    std::vector<Point> sortedPoints(points.size());
    std::copy_if(points.begin(), points.end(), sortedPoints.begin(), [lowest](Point const& p) {
        return p!= lowest;
    });
    std::sort(sortedPoints.begin(), sortedPoints.end(), [lowest](Point const& a, Point const& b) {
        double angleA = std::atan2(a.y - lowest.y, a.x - lowest.x);
        double angleB = std::atan2(b.y - lowest.y, b.x - lowest.x);
        return angleA < angleB || (angleA == angleB && (a.x - lowest.x) * (a.x - lowest.x) + (a.y - lowest.y) * (a.y - lowest.y) < (b.x - lowest.x) * (b.x - lowest.x) + (b.y - lowest.y) * (b.y - lowest.y));
    });

    // Merge the sorted points with the lowest point
    sortedPoints.insert(sortedPoints.begin(), lowest);

    // Compute the convex hull
    std::vector<Point> stack;
    stack.reserve(sortedPoints.size());
    for (size_t i = 0; i < sortedPoints.size(); ++i) {
        while (stack.size() >= 2) {
            Point const& p1 = stack[stack.size() - 2];
            Point const& p2 = stack[stack.size() - 1];
            Point const& p3 = sortedPoints[i];
            if ((p3.x - p2.x) * (p2.y - p1.y) - (p2.x - p1.x) * (p3.y - p2.y) <= 0) {
                stack.pop_back();
            } else {
                break;
            }
        }
        stack.push_back(sortedPoints[i]);
    }

    hull = stack;
}

