void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Find the leftmost point
    auto leftmost = std::min_element(points.begin(), points.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Sort the points by polar angle with the leftmost point
    std::vector<Point> sortedPoints;
    sortedPoints.reserve(points.size());
    for (auto& p : points) {
        if (&p!= leftmost) {
            sortedPoints.push_back(p);
        }
    }
    std::sort(sortedPoints.begin(), sortedPoints.end(), [&](Point const& a, Point const& b) {
        double angleA = std::atan2(a.y - leftmost->y, a.x - leftmost->x);
        double angleB = std::atan2(b.y - leftmost->y, b.x - leftmost->x);
        return angleA < angleB || (angleA == angleB && (a.x < b.x || (a.x == b.x && a.y < b.y)));
    });

    // Build the convex hull
    hull.reserve(points.size());
    hull.push_back(*leftmost);
    for (auto& p : sortedPoints) {
        while (hull.size() > 1) {
            Point& last = hull[hull.size() - 1];
            Point& secondLast = hull[hull.size() - 2];
            if ((last.x - secondLast.x) * (p.y - secondLast.y) - (last.y - secondLast.y) * (p.x - secondLast.x) >= 0) {
                break;
            }
            hull.pop_back();
        }
        hull.push_back(p);
    }
