#include <vector>
#include <immintrin.h>

void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    for (size_t i = 0; i < M; i++) {
        y[i] = 0;
    }

    size_t j;
    for (j = 0; j < N; j += 4) {
        __m256d x_val = _mm256_loadu_pd(&x[j]);
        for (size_t i = 0; i < M; i++) {
            __m256d a_val = _mm256_loadu_pd(&A[i * N + j]);
            __m256d prod = _mm256_mul_pd(a_val, x_val);
            __m256d sum = _mm256_loadu_pd(&y[i]);
            sum = _mm256_add_pd(sum, prod);
            _mm256_storeu_pd(&y[i], sum);
        }
    }

    // Handle remaining elements
    for (; j < N; j++) {
        for (size_t i = 0; i < M; i++) {
            y[i] += A[i * N + j] * x[j];
        }
    }
}

