void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    for (size_t i = 0; i < M; i++) {
        double sum = 0;
        size_t j = 0;
        // Process 4 elements at a time using SIMD instructions
        for (; j + 4 <= N; j += 4) {
            __m256d av = _mm256_loadu_pd(&A[i * N + j]);
            __m256d bv = _mm256_loadu_pd(&x[j]);
            __m256d cv = _mm256_mul_pd(av, bv);
            __m256d sumv = _mm256_loadu_pd(&sum);
            sumv = _mm256_add_pd(sumv, cv);
            _mm256_store_pd(&sum, sumv);
        }
        // Horizontal addition of the SIMD result
        for (double d : sum) {
            sum += d;
        }
        // Process remaining elements
        for (; j < N; j++) {
            sum += A[i * N + j] * x[j];
        }
        y[i] = sum;
    }
}

