void luFactorize(std::vector<double> &A, size_t N) {
    for (size_t k = 0; k < N; ++k) {
        // Compute multipliers for the current row
        __m256d multipliers = _mm256_div_pd(_mm256_loadu_pd(&A[k * N + k]), _mm256_loadu_pd(&A[k * N + k]));

        for (size_t i = k + 1; i < N; i += 4) {
            // Load the current row
            __m256d currentRow = _mm256_loadu_pd(&A[i * N + k]);

            // Compute the factor and store it in the current row
            __m256d factor = _mm256_div_pd(currentRow, _mm256_loadu_pd(&A[k * N + k]));
            _mm256_storeu_pd(&A[i * N + k], factor);

            // Update the remaining elements of the current row
            for (size_t j = k + 1; j < N; j++) {
                A[i * N + j] -= A[k * N + j] * factor[j - k - 1];
            }
        }
    }
}

