void ranks(std::vector<float> const& x, std::vector<size_t> &ranks_) {
    // Create a vector of indices
    std::vector<size_t> indices(x.size());
    std::iota(indices.begin(), indices.end(), 0);

    // Sort indices based on corresponding values in x
    #pragma omp parallel
    {
        #pragma omp single
        {
            // Use insertion sort for small vectors
            if (x.size() < 16) {
                for (size_t i = 1; i < indices.size(); ++i) {
                    size_t key = indices[i];
                    float value = x[key];
                    size_t j = i - 1;
                    while (j < indices.size() && x[indices[j]] > value) {
                        indices[j + 1] = indices[j];
                        --j;
                    }
                    indices[j + 1] = key;
                }
            } else {
                // Use std::sort for larger vectors
                std::sort(indices.begin(), indices.end(), [&x](size_t i1, size_t i2) {
                    return x[i1] < x[i2];
                });
            }
        }
    }

    // Fill ranks_ in a single pass
    #pragma omp parallel for
    for (size_t i = 0; i < indices.size(); ++i) {
        ranks_[indices[i]] = i;
    }
}

