void sortByStartTime(std::vector<Result> &results) {
   if (results.size() < 1000) {
      std::sort(results.begin(), results.end(), [](Result const& a, Result const& b) {
         return a.startTime < b.startTime;
      });
   } else {
      #pragma omp parallel
      {
         #pragma omp single
         {
            int n = results.size();
            int threshold = 100;
            int numThreads = omp_get_num_threads();
            int chunk_size = (n + numThreads - 1) / numThreads;
            int start, end;

            #pragma omp taskgroup
            {
               for (int i = 0; i < numThreads; i++) {
                  start = i * chunk_size;
                  end = std::min(start + chunk_size, n);
                  if (end - start > threshold) {
                     #pragma omp task
                     {
                        std::sort(results.begin() + start, results.begin() + end, [](Result const& a, Result const& b) {
