void sortComplexByMagnitudeSIMD(std::vector<std::complex<double>> &x) {
    const size_t size = x.size();
    if (size < 16) {
        sortComplexByMagnitude(x);
        return;
    }

    // Use SIMD for larger sizes
    __m256d abs_a, abs_b;
    for (size_t i = 0; i < size; i += 4) {
        // Load 4 complex numbers
        __m256d real_a = _mm256_loadu_pd(&x[i].real());
        __m256d imag_a = _mm256_loadu_pd(&x[i].imag());

        // Compute absolute values
        abs_a = _mm256_sqrt_pd(_mm256_mul_pd(real_a, real_a) + _mm256_mul_pd(imag_a, imag_a));

        // Sorting for the first 4
        for (size_t j = 0; j < 3; ++j) {
            for (size_t k = j + 1; k < 4; ++k) {
                // Load the next complex number
                __m256d real_b = _mm256_loadu_pd(&x[i + k].real());
                __m256d imag_b = _mm256_loadu_pd(&x[i + k].imag());
                abs_b = _mm256_sqrt_pd(_mm256_mul_pd(real_b, real_b) + _mm256_mul_pd(imag_b, imag_b));

                // Compare absolute values
                __m256d cmp = _mm256_cmp_pd(abs_a, abs_b, _CMP_LT_OQ);
                if (_mm256_testz_si256(_mm256_castpd_si256(cmp), _mm256_set1_epi64x(-1))) {
                    continue;
                }

                // Swap
                _mm256_storeu_pd(&x[i + j].real(), real_b);
                _mm256_storeu_pd(&x[i + j].imag(), imag_b);
                _mm256_storeu_pd(&x[i + k].real(), real_a);
                _mm256_storeu_pd(&x[i + k].imag(), imag_a);

                // Update abs_a and abs_b
                abs_a = abs_b;
                real_a = real_b;
                imag_a = imag_b;
            }
        }
    }
}

