#include <complex>
#include <vector>
#include <algorithm>
#include <omp.h>

void insertionSort(std::vector<std::complex<double>> &x, int start, int end) {
    for (int i = start + 1; i <= end; i++) {
        std::complex<double> key = x[i];
        int j = i - 1;

        while (j >= start && std::abs(x[j]) > std::abs(key)) {
            x[j + 1] = x[j];
            j--;
        }
        x[j + 1] = key;
    }
}

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    int n = x.size();
    if (n < 16) {
        insertionSort(x, 0, n - 1);
        return;
    }

    int threshold = 16;
    #pragma omp parallel
    {
        #pragma omp single
        {
            int numThreads = omp_get_num_threads();
            int chunkSize = (n + numThreads - 1) / numThreads;
            int start, end;

            #pragma omp for
            for (int i = 0; i < numThreads; i++) {
                start = i * chunkSize;
                end = std::min(start + chunkSize - 1, n - 1);
                insertionSort(x, start, end);
            }
        }
    }

    // Merge sorted chunks
    #pragma omp parallel
    {
        #pragma omp single
        {
            int step = 1;
            while (step < n) {
                int left = 0;
                #pragma omp for
                for (int i = 0; i < n; i += step * 2) {
                    int mid = i + step - 1;
                    int right = std::min(i + step * 2 - 1, n - 1);
                    if (mid < right) {
                        // Merge the two sorted subarrays
                        int start1 = left, end1 = mid;
                        int start2 = mid + 1, end2 = right;
                        std::vector<std::complex<double>> temp(right - left + 1);
                        int index = 0;
                        while (start1 <= end1 && start2 <= end2) {
                            if (std::abs(x[start1]) < std::abs(x[start2])) {
                                temp[index++] = x[start1++];
                            } else {
                                temp[index++] = x[start2++];
                            }
                        }
                        while (start1 <= end1) {
                            temp[index++] = x[start1++];
                        }
                        while (start2 <= end2) {
                            temp[index++] = x[start2++];
                        }
                        // Copy the merged temporary array back to the original vector
                        for (int j = 0; j < index; j++) {
                            x[left + j] = temp[j];
                        }
                    }
                    left += step * 2;
                }
                step *= 2;
            }
        }
    }
}

