int findKthSmallest(std::vector<int> const& x, int k) {
    // Create a copy of the input vector to avoid modifying the original
    std::vector<int> x_copy = x;

    // Use a threshold for small input sizes to avoid overhead of parallelism
    const size_t n = x_copy.size();
    const size_t threshold = 100;

    if (n <= threshold) {
        std::sort(x_copy.begin(), x_copy.end());
        return x_copy[k-1];
    }

    // Use OpenMP to parallelize the sorting process for larger inputs
    #pragma omp parallel
    {
        #pragma omp single
        {
            // Divide the vector into segments and sort each segment in parallel
            #pragma omp taskgroup
            {
                const size_t segment_size = n / omp_get_num_threads();
                #pragma omp task shared(x_copy)
                {
                    size_t start = 0;
                    size_t end = std::min(start + segment_size, n);
                    std::sort(x_copy.begin() + start, x_copy.begin() + end);
                }
                // Generate tasks for each segment
                for (size_t i = 1; i < omp_get_num_threads(); ++i) {
                    size_t start = i * segment_size;
                    size_t end = std::min(start + segment_size, n);
                    #pragma omp task shared(x_copy)
                    {
                        std::sort(x_copy.begin() + start, x_copy.begin() + end);
                    }
                }
            }
        }
    }

    // Merge the sorted segments
    std::inplace_merge(x_copy.begin(), x_copy.begin() + segment_size, x_copy.end());

    return x_copy[k-1];
}

