    size_t index = 0;
    double minDiff = std::abs(x[0] - M_PI);

    // Use OpenMP for parallel processing on larger vectors
    size_t size = x.size();
    if (size > 1000) {
        double globalMin = minDiff;
        #pragma omp parallel
        {
            double localMin = globalMin;
            size_t localIndex = 0;
            #pragma omp for
            for (size_t i = 0; i < size; ++i) {
                double diff = std::abs(x[i] - M_PI);
                if (diff < localMin) {
                    localMin = diff;
                    localIndex = i;
                }
            }
            // Critical section to update the global minimum safely in a thread-safe manner
            #pragma omp critical
            {
                if (localMin < globalMin) {
                    globalMin = localMin;
                    index = localIndex;
                }
            }
        }
    } else {
        // Sequential search for smaller vectors
        for (size_t i = 0; i < size; ++i) {
            double diff = std::abs(x[i] - M_PI);
            if (diff < minDiff) {
                minDiff = diff;
                index = i;
            }
        }
    }
    return index;
}

